def task_2b_solution(G, community):
    # If the community has only one node, density is defined as 1
    n = len(community)
    if n <= 1:
        return 1

    # Count intra-community edges
    num_intra_edges = 0
    for u, v in G.edges():
        if u in community and v in community:
            num_intra_edges += 1

    # Density formula
    density = 2 * num_intra_edges / (n * (n - 1))
    return density

